text:
{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summary の hs",
      "detail": "stdにある「交付決定を受けた法人は1年間政治献金が禁止される」や「補助金適正化法」などの重要な情報が大幅に抜け落ちており、補助金の説明だけになっているため。",
      "fix": "stdに合わせて、補助金適正化法や1年間の政治献金禁止に関する記述を補う。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdが補助金を受ける場合の義務や制限についての問いかけであるのに対し、hsは「もとはだれのお金でしょう？」という全く異なる問いかけになっており、中身がずれているため。",
      "fix": "stdの内容に合わせ、「国から補助金を受けると、どんなルールや制限があるのでしょうか？」などに直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/0/text の hs",
      "detail": "stdにある「各省各庁の長に」という申請先についての情報が抜けているため。",
      "fix": "申請先が国（各省各庁の長）であることを補う。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/1/text の hs",
      "detail": "stdにある「各省各庁の長が」「条件を付すことができる」という情報が抜け落ちているため。",
      "fix": "国（各省各庁の長）が審査して決定し、条件をつけられることを盛り込む。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/2/text の hs",
      "detail": "stdにある「実績報告」「国が額を確定」という具体的なステップが抜けており、抽象的な説明になっているため。",
      "fix": "仕事が終わったあとの報告と、国による額の決定について盛り込む。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/3/text の hs",
      "detail": "stdにある「5年以下の拘禁刑若しくは100万円以下の罰金（第29条）」という具体的な罰則の数字や内容が抜けているため。",
      "fix": "うそをついた場合の具体的な罰則についての言及を補う。"
    },
    {
      "type": "評価・意見",
      "where": "blocks/2/text の hs",
      "detail": "stdにない「お金をもらう会社が政治家側にお金を出すことを防ぐためのルールです。」という解説（評価・理由付け）が追加されているため。",
      "fix": "追加した理由付けの文を削除し、stdの事実のみに書き直す。"
    }
  ]
}
